// Package garmin drives the garmin-fetch CLI (see garmin-fetch/README.md)
// and imports the downloaded original FIT files.
//
// garmin-fetch is a subprocess per operation: stdout carries JSON Lines
// events, stderr logs, stdin secrets. The exit code tells whether to ask the
// user to log in again (2), back off (3) or retry later (1).
package garmin

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// TokenFile is the name of the token store written by python-garminconnect.
const TokenFile = "garmin_tokens.json"

var (
	// ErrAuthRequired means the tokens are missing, expired or were rejected.
	ErrAuthRequired = errors.New("Anmeldung bei Garmin Connect erforderlich")
	// ErrRateLimited means Garmin throttles requests; retry much later.
	ErrRateLimited = errors.New("Garmin Connect begrenzt die Anfragen, später erneut versuchen")
	// ErrMFAFailed means the MFA step failed.
	ErrMFAFailed = errors.New("Bestätigungscode abgelehnt oder abgelaufen")
	// ErrUnavailable means garmin-fetch is not installed (e.g. local development).
	ErrUnavailable = errors.New("garmin-fetch ist nicht verfügbar")
)

// Event is one line of garmin-fetch output.
type Event struct {
	Event      string `json:"event"`
	Status     string `json:"status,omitempty"`
	Code       string `json:"code,omitempty"`
	Message    string `json:"message,omitempty"`
	File       string `json:"file,omitempty"`
	ActivityID string `json:"activity_id,omitempty"`
	Name       string `json:"name,omitempty"`
	Type       string `json:"type,omitempty"`
	Listed     int    `json:"listed,omitempty"`
	Downloaded int    `json:"downloaded,omitempty"`
	Skipped    int    `json:"skipped,omitempty"`
	NoFile     int    `json:"no_file,omitempty"`
}

// Runner starts garmin-fetch.
type Runner struct {
	// Command is the executable and leading arguments, default
	// ["garmin-fetch"]; tests replace it with a fake.
	Command  []string
	TokenDir string
	Logger   *slog.Logger
}

func (r *Runner) command() []string {
	if len(r.Command) == 0 {
		return []string{"garmin-fetch"}
	}
	return r.Command
}

func (r *Runner) logger() *slog.Logger {
	if r.Logger != nil {
		return r.Logger
	}
	return slog.New(slog.DiscardHandler)
}

// Available reports whether garmin-fetch can be started.
func (r *Runner) Available() bool {
	_, err := exec.LookPath(r.command()[0])
	return err == nil
}

// HasTokens reports whether a token store exists (not whether it is valid).
func (r *Runner) HasTokens() bool {
	_, err := os.Stat(filepath.Join(r.TokenDir, TokenFile))
	return err == nil
}

// Logout removes the stored tokens.
func (r *Runner) Logout() error {
	err := os.Remove(filepath.Join(r.TokenDir, TokenFile))
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	return err
}

// process is a running garmin-fetch invocation.
type process struct {
	cmd    *exec.Cmd
	stdin  io.WriteCloser
	events chan Event
	stderr *strings.Builder
}

func (r *Runner) start(ctx context.Context, args ...string) (*process, error) {
	if !r.Available() {
		return nil, ErrUnavailable
	}
	// garmin-fetch <subcommand> --tokenstore DIR [options]
	argv := append(append([]string{}, r.command()...), args[0], "--tokenstore", r.TokenDir)
	argv = append(argv, args[1:]...)
	cmd := exec.CommandContext(ctx, argv[0], argv[1:]...)
	cmd.WaitDelay = 5 * time.Second
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return nil, err
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	p := &process{cmd: cmd, stdin: stdin, events: make(chan Event, 16), stderr: &strings.Builder{}}
	cmd.Stderr = limitedWriter{p.stderr, 64 << 10}
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	go func() {
		defer close(p.events)
		sc := bufio.NewScanner(stdout)
		sc.Buffer(make([]byte, 64<<10), 1<<20)
		for sc.Scan() {
			var ev Event
			if err := json.Unmarshal(sc.Bytes(), &ev); err != nil {
				r.logger().Warn("garmin-fetch: unexpected output", "line", truncate(sc.Text(), 200))
				continue
			}
			p.events <- ev
		}
	}()
	return p, nil
}

// wait collects the exit status after all events were consumed and maps it to
// the package errors. lastErr is the last "error" event, if any.
func (p *process) wait(lastErr *Event) error {
	err := p.cmd.Wait()
	if err == nil {
		return nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		switch exitErr.ExitCode() {
		case 2:
			return ErrAuthRequired
		case 3:
			return ErrRateLimited
		case 4:
			return ErrMFAFailed
		}
	}
	if lastErr != nil && lastErr.Message != "" {
		return fmt.Errorf("garmin-fetch: %s (%s)", lastErr.Message, lastErr.Code)
	}
	if msg := strings.TrimSpace(p.stderr.String()); msg != "" {
		return fmt.Errorf("garmin-fetch: %w: %s", err, truncate(lastLine(msg), 300))
	}
	return fmt.Errorf("garmin-fetch: %w", err)
}

// Status checks whether the stored tokens are accepted.
func (r *Runner) Status(ctx context.Context) error {
	if !r.HasTokens() {
		return ErrAuthRequired
	}
	p, err := r.start(ctx, "status")
	if err != nil {
		return err
	}
	p.stdin.Close()
	var lastErr *Event
	for ev := range p.events {
		if ev.Event == "error" {
			e := ev
			lastErr = &e
		}
	}
	return p.wait(lastErr)
}

// SyncOptions controls a download run.
type SyncOptions struct {
	Since    time.Time
	Inbox    string
	KnownIDs []string
	Delay    time.Duration
}

// Sync downloads activities since opts.Since that are not in KnownIDs into
// the inbox and reports every event to onEvent while it runs.
func (r *Runner) Sync(ctx context.Context, opts SyncOptions, onEvent func(Event)) (Event, error) {
	if err := os.MkdirAll(opts.Inbox, 0o750); err != nil {
		return Event{}, err
	}
	known, err := os.CreateTemp(opts.Inbox, ".known-*.txt")
	if err != nil {
		return Event{}, err
	}
	defer os.Remove(known.Name())
	if _, err := known.WriteString(strings.Join(opts.KnownIDs, "\n")); err != nil {
		known.Close()
		return Event{}, err
	}
	known.Close()

	p, err := r.start(ctx, "sync", "--out", opts.Inbox, "--since", opts.Since.Format(time.DateOnly),
		"--known-ids", known.Name(), "--delay", fmt.Sprintf("%.1f", opts.Delay.Seconds()))
	if err != nil {
		return Event{}, err
	}
	p.stdin.Close()
	var done Event
	var lastErr *Event
	for ev := range p.events {
		switch ev.Event {
		case "done":
			done = ev
		case "error":
			e := ev
			lastErr = &e
		}
		if onEvent != nil {
			onEvent(ev)
		}
	}
	return done, p.wait(lastErr)
}

type limitedWriter struct {
	b     *strings.Builder
	limit int
}

func (w limitedWriter) Write(p []byte) (int, error) {
	if room := w.limit - w.b.Len(); room > 0 {
		if len(p) > room {
			w.b.Write(p[:room])
		} else {
			w.b.Write(p)
		}
	}
	return len(p), nil
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

func lastLine(s string) string {
	if i := strings.LastIndexByte(s, '\n'); i >= 0 {
		return s[i+1:]
	}
	return s
}
